using System;
using UnityEngine;

/// <summary>
/// SO event channel raised on every successful resource hit. Carries the struck
/// <see cref="ResourceNode"/> and its remaining health fraction (0-1) so listeners
/// (the HUD world-anchored HP bar) can position and fill a bar without holding a direct
/// reference to the node. Decouples resources from UI per the Architect rules.
/// </summary>
[CreateAssetMenu(menuName = "Flynn/Resource/Hit Channel", fileName = "ResourceHitChannel")]
public class ResourceHitChannel : ScriptableObject
{
    /// <summary>(node, health01) — health01 is CurrentHealth / maxHealth after the hit.</summary>
    public event Action<ResourceNode, float> OnHit;

    public void Raise(ResourceNode node, float health01)
    {
        if (node == null) return;
        OnHit?.Invoke(node, Mathf.Clamp01(health01));
    }
}

using System;
using UnityEngine;

[CreateAssetMenu(menuName = "Dialogue/Trigger Channel", fileName = "DialogueTriggers")]
public class DialogueTriggerChannel : ScriptableObject
{
    public event Action<DialogueTriggerPayload> OnRaised;

    public void Raise(DialogueTriggerPayload payload)
    {
        if (string.IsNullOrWhiteSpace(payload.triggerKey)) return;
        OnRaised?.Invoke(payload);
    }

    public void Raise(string triggerKey, string sourceNpcId)
        => Raise(triggerKey, sourceNpcId, null, null);

    public void Raise(string triggerKey, string sourceNpcId, string handler, string payloadJson)
    {
        Raise(new DialogueTriggerPayload
        {
            triggerKey = triggerKey,
            sourceNpcId = sourceNpcId ?? string.Empty,
            handler = handler ?? string.Empty,
            payloadJson = payloadJson ?? string.Empty,
            topic = "none",
        });
    }
}

public struct DialogueTriggerPayload
{
    /// Signal id (matches a SignalContent.signalId in the island JSON).
    public string triggerKey;
    /// Id of the NPC that fired it. Empty when fired from a non-dialogue source.
    public string sourceNpcId;
    /// Handler category from the authored signal (IslandContentVocab.SignalHandlers).
    /// Optional — listeners usually match on triggerKey, but may route on this.
    public string handler;
    /// Opaque payload string from the authored signal (usually JSON). Delivered
    /// verbatim so a handler can interpret it.
    public string payloadJson;
    public string topic;
    public int trustDelta;

    public string Key => triggerKey;
}

using UnityEngine;

/// <summary>
/// Single-responsibility component that owns all mouse → world target detection. Every interaction
/// reads what's under the cursor from here; nothing keeps its own proximity registry.
///
/// It no longer casts its own rays: <see cref="MousePointer"/> does ONE cursor raycast per frame
/// (against its combined world mask) and this component derives every hovered target from that one
/// shared hit. The object under the cursor is resolved once; each concern asks it for the component
/// it cares about and applies its own range gate. Consequence of the single union cast: the closest
/// object under the cursor wins across all layers (uniform occlusion) — there are no per-concern
/// masks that can see a target through something in front of it.
///
/// Other systems read the public properties; this component only ever reads — it writes nothing.
/// Requires a <see cref="MousePointer"/> in the scene whose mask covers ground + resources + pickups
/// + grapple + melee surfaces (the union of what used to be per-concern masks here).
/// </summary>
[RequireComponent(typeof(SolarpunkCharacterController))]
public class PlayerMouseAimer : MonoBehaviour
{
    [SerializeField] private float _maxAimDistance = 30f;

    [Tooltip("Max distance from the player to a resource or pickup for it to count as interactable.")]
    [SerializeField] private float _interactionRange = 3f;

    [Tooltip("Max distance from the player to a melee surface for a wrench swing to register its tool/hit.")]
    [SerializeField] private float _meleeRange = 2.5f;

    private MousePointer _pointer;

    // ── Public properties ─────────────────────────────────────────────────────

    /// <summary>World-space position the mouse cursor is pointing at.</summary>
    public Vector3 WorldAimPoint { get; private set; }

    /// <summary>
    /// The ResourceNode the mouse ray is pointing at, or null.
    /// Only set when the hit node is within <see cref="_interactionRange"/> of the player.
    /// </summary>
    public ResourceNode HoveredResource { get; private set; }

    /// <summary>
    /// The WorldItemPickup the mouse ray is pointing at, or null. (Legacy; new world objects use
    /// <see cref="WorldItem"/> / <see cref="HoveredKeyPickup"/>.) Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItemPickup HoveredPickup { get; private set; }

    /// <summary>
    /// The non-auto-collect <see cref="WorldItem"/> under the cursor (e.g. the wrench), or null.
    /// These require the pickup key — auto-collecting items magnet themselves and never appear here.
    /// Range-gated by <see cref="_interactionRange"/>.
    /// </summary>
    public WorldItem HoveredKeyPickup { get; private set; }

    /// <summary>The RopeAnchor the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopeAnchor HoveredAnchor { get; private set; }

    /// <summary>The RopePullable the mouse ray is pointing at, or null. Not range-gated (the controller gates).</summary>
    public RopePullable HoveredPullable { get; private set; }

    /// <summary>Exact world surface point hit on the current grapple target. Valid only when an anchor or pullable is hovered.</summary>
    public Vector3 HoveredGrapplePoint { get; private set; }

    /// <summary>
    /// Animator AttackIndex of the surface under the cursor within <see cref="_meleeRange"/>.
    /// Defaults to 4 (wrench / "air") when nothing meleeable is in reach. The wrench swing
    /// reads this to decide which tool to transform into.
    /// </summary>
    public int SwingAnimIndex { get; private set; } = 4;

    /// <summary>
    /// The ResourceNode under the cursor within melee reach, or null. Used by the swing to
    /// apply harvest damage. Non-resource surfaces (HittableSurface) drive the tool anim but
    /// leave this null (no damage).
    /// </summary>
    public ResourceNode MeleeResource { get; private set; }

    /// <summary>
    /// The interaction-prompt provider the player is currently targeting (pickup, grapple point,
    /// NPC, …), or null. Generic — the HUD reads this and renders whatever prompt it returns.
    /// </summary>
    public IInteractionPromptProvider HoveredInteractable { get; private set; }

    /// <summary>The GameObject the mouse ray is pointing at (from MousePointer), or null.</summary>
    public GameObject HoveredGameObject
    {
        get
        {
            if (_pointer == null) _pointer = MousePointer.Instance;
            return _pointer != null ? _pointer.HoverObject : null;
        }
    }

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Update()
    {
        if (_pointer == null) _pointer = MousePointer.Instance;
        if (_pointer == null) return;

        GameObject hovered = _pointer.HoverObject;
        bool hasHit = _pointer.HasHit;
        Vector3 point = _pointer.WorldPoint;

        UpdateAimPoint(hasHit, point);
        UpdateHoveredResource(hovered);
        UpdateHoveredPickup(hovered);
        UpdateHoveredKeyPickup(hovered);
        UpdateHoveredGrapple(hovered, point);
        UpdateMeleeTarget(hovered, hasHit, point);
        UpdateHoveredInteractable(hovered, hasHit, point);
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void UpdateAimPoint(bool hasHit, Vector3 point)
    {
        if (hasHit)
        {
            WorldAimPoint = point;
            return;
        }
        // Miss: intersect the horizontal plane at this object's Y so aim still resolves over open ground.
        var plane = new Plane(Vector3.up, new Vector3(0f, transform.position.y, 0f));
        if (plane.Raycast(_pointer.WorldRay, out float dist))
            WorldAimPoint = _pointer.WorldRay.GetPoint(Mathf.Min(dist, _maxAimDistance));
    }

    private void UpdateHoveredResource(GameObject hovered)
    {
        ResourceNode node = Find<ResourceNode>(hovered);
        HoveredResource = node != null && WithinInteractionRange(node.transform.position) ? node : null;
    }

    private void UpdateHoveredPickup(GameObject hovered)
    {
        WorldItemPickup pickup = Find<WorldItemPickup>(hovered);
        HoveredPickup = pickup != null && WithinInteractionRange(pickup.transform.position) ? pickup : null;
    }

    private void UpdateHoveredKeyPickup(GameObject hovered)
    {
        WorldItem item = Find<WorldItem>(hovered);
        // Only key-pickup items (e.g. the wrench) surface here; auto-collect items magnet themselves.
        bool needsKey = item != null && item.Item != null && !item.Item.AutoCollects;
        HoveredKeyPickup = needsKey && WithinInteractionRange(item.transform.position) ? item : null;
    }

    private void UpdateHoveredGrapple(GameObject hovered, Vector3 point)
    {
        // Whichever marker the hovered object carries decides the kind; range is left to the
        // controller (RopeLassoConfig owns it). Anchor and pullable are mutually exclusive.
        RopeAnchor anchor = Find<RopeAnchor>(hovered);
        if (anchor != null)
        {
            HoveredAnchor = anchor;
            HoveredPullable = null;
            HoveredGrapplePoint = point;
            return;
        }

        RopePullable pullable = Find<RopePullable>(hovered);
        HoveredAnchor = null;
        HoveredPullable = pullable;
        if (pullable != null) HoveredGrapplePoint = point;
    }

    private void UpdateMeleeTarget(GameObject hovered, bool hasHit, Vector3 point)
    {
        // ResourceNode wins (it carries damage + its own tool); otherwise a HittableSurface decides
        // the tool; nothing in reach = wrench (air).
        MeleeResource = null;
        SwingAnimIndex = 4;
        if (!hasHit || hovered == null) return;
        if (Vector3.Distance(transform.position, point) > _meleeRange) return;

        ResourceNode node = Find<ResourceNode>(hovered);
        if (node != null)
        {
            MeleeResource = node;
            SwingAnimIndex = node.AttackAnimIndex;
            return;
        }

        HittableSurface surface = Find<HittableSurface>(hovered);
        if (surface != null)
            SwingAnimIndex = surface.AttackAnimIndex;
    }

    private void UpdateHoveredInteractable(GameObject hovered, bool hasHit, Vector3 point)
    {
        HoveredInteractable = null;

        // 1) Generic interaction target within reach — pickups, NPCs, inspectables, etc.
        if (hasHit && hovered != null && Vector3.Distance(transform.position, point) <= _interactionRange)
        {
            var provider = hovered.GetComponentInParent<IInteractionPromptProvider>();
            if (provider != null) { HoveredInteractable = provider; return; }
        }

        // 2) Fall back to the rope-lasso targets (their reach is owned by the lasso controller,
        //    so they prompt even past the generic interaction range).
        if (HoveredAnchor is IInteractionPromptProvider anchor)        HoveredInteractable = anchor;
        else if (HoveredPullable is IInteractionPromptProvider pull)   HoveredInteractable = pull;
    }

    /// <summary>Component of type T on the hovered object or its parents, or null.</summary>
    private static T Find<T>(GameObject hovered) where T : Component
        => hovered != null ? hovered.GetComponentInParent<T>() : null;

    private bool WithinInteractionRange(Vector3 worldPos)
        => Vector3.Distance(transform.position, worldPos) <= _interactionRange;
}

using UnityEngine;

/// <summary>
/// Immutable payload for a single player "hit" event (a swing/strike landing). Carried by
/// <see cref="PlayerHitChannel"/> from the player to the <see cref="ResourceManager"/>, which
/// re-broadcasts it to registered resources. Deliberately generic: it describes WHAT happened,
/// not WHO should react — the resource layer decides that later.
/// </summary>
public readonly struct PlayerHitInfo
{
    /// <summary>World-space point the hit landed at.</summary>
    public readonly Vector3 Point;

    /// <summary>The struck GameObject, if the player resolved one. May be null (whiffed swing).</summary>
    public readonly GameObject Target;

    /// <summary>Generic strike strength. Unused for now; here so damage can be wired in later.</summary>
    public readonly int Power;

    public PlayerHitInfo(Vector3 point, GameObject target, int power)
    {
        Point = point;
        Target = target;
        Power = power;
    }
}

using UnityEngine;

/// <summary>
/// Player startup script. Thin for now — owns the player's wiring to the <see cref="ResourceManager"/>:
/// it subscribes to resource events on startup (the place to add player-side reactions later) and is
/// the publisher that raises player hits via <see cref="EmitHit"/>. Combat is not wired in yet; a
/// debug key raises a test hit so the player → manager → resource pipe is verifiable in Play mode.
///
/// Expand this as the player gains more init responsibilities.
/// </summary>
public class PlayerInitializer : MonoBehaviour
{
    [Header("Debug")]
    [Tooltip("Press to raise a test hit at the player's position (verifies the event pipe). None = disabled.")]
    [SerializeField] private KeyCode _debugHitKey = KeyCode.None;

    private void OnEnable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit += HandleResourceHit;
    }

    private void OnDisable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit -= HandleResourceHit;
    }

    private void Update()
    {
        if (_debugHitKey != KeyCode.None && Input.GetKeyDown(_debugHitKey))
            EmitHit(transform.position, null, 1);
    }

    /// <summary>Publisher: raise a player hit through the manager. Call this when a swing lands.</summary>
    public void EmitHit(Vector3 point, GameObject target = null, int power = 1)
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.RaiseHit(new PlayerHitInfo(point, target, power));
    }

    /// <summary>Player-side reaction to resource events. Empty hook for now.</summary>
    private void HandleResourceHit(PlayerHitInfo info) { }
}

using UnityEngine;

/// <summary>
/// Left-click swing for the wrench multitool. Simple tap with a short cooldown
/// to prevent spam. The swing faces the mouse aim point. Routes damage through
/// the ResourceManager observer pattern. Disabled while the wrench is airborne (thrown).
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    [Tooltip("Directional swipe arc visual. Fed the player→mouse direction on each swing.")]
    [SerializeField] private WrenchSwingArc _swingArc;

    [Tooltip("Cooldown between swings (seconds).")]
    [SerializeField] private float _cooldownTime = 0.1f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private IPlayerVisual _animDriver;
    private float _cooldown;

    public bool IsCharging => false;
    public float ChargeNormalized => 0f;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
    }

    private void Update()
    {
        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable) return;

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
            DoSwing();
    }

    private void DoSwing()
    {
        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);

        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float speed = _config != null ? _config.lightSwingAnimSpeed : 1.0f;
        if (_animDriver != null)
            _animDriver.ReleaseSwing(animIndex, speed);

        if (_swingArc != null)
            _swingArc.Play(_aimer.WorldAimPoint);

        _cooldown = _cooldownTime;

        // Route hit through the ResourceManager observer pattern.
        int damage = _config != null ? _config.lightSwingDamage : 1;
        GameObject target = _aimer.HoveredGameObject;
        if (_playerInit != null && damage > 0)
            _playerInit.EmitHit(_aimer.WorldAimPoint, target, damage);
    }
}

using UnityEngine;

/// <summary>
/// Right-click throw for the wrench. Tap = short throw; hold to charge for a longer
/// throw (distance scales min→max with charge). Spawns a ThrownWrench projectile that
/// flies to the target, hovers, then boomerangs back to the player and is caught.
/// Only one throw may be airborne at a time. Exposes IsCharging / ChargeNormalized /
/// IsAirborne for the aim reticle and the swing controller.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchThrowController : MonoBehaviour
{
    [SerializeField] private WrenchConfig _config;
    [SerializeField] private GameObject _thrownWrenchPrefab;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private ThrownWrench _airborne;
    private float _chargeTimer;
    private bool _charging;

    public bool IsCharging => _charging;
    public bool IsAirborne => _airborne != null;
    public float ChargeNormalized => _config != null && _config.throwChargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.throwChargeTime)
        : 0f;

    /// <summary>
    /// World-space hand position: the billboard visual centre, so the wrench
    /// appears to leave from and return to the sprite rather than the physics root.
    /// </summary>
    public Vector3 CatchPoint =>
        _animDriver != null ? _animDriver.VisualCenter : transform.position;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
    }

    private void Update()
    {
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !IsAirborne;
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetMouseButtonDown(1))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetMouseButton(1))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetMouseButtonUp(1))
        {
            DoThrow();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void DoThrow()
    {
        if (_thrownWrenchPrefab == null || _config == null) return;

        // Use the billboard's visual centre as origin so distance/direction is
        // measured from where the sprite appears on screen, not from the feet.
        Vector3 origin = CatchPoint;

        // Direction on the XZ plane from the visual centre to the aim point.
        Vector3 toAim = _aimer.WorldAimPoint - origin;
        toAim.y = 0f;
        if (toAim.sqrMagnitude < 0.0001f) toAim = transform.forward;

        // Charge gates maximum reach. If the cursor is closer than that, the wrench
        // lands exactly on it; if farther, it stops at the charge-limited range.
        float maxDist = Mathf.Lerp(_config.minThrowDistance, _config.maxThrowDistance, ChargeNormalized);
        float dist = Mathf.Min(toAim.magnitude, maxDist);

        Vector3 target = origin + toAim.normalized * dist;
        // Restore the aim Y so the wrench lands at the actual world surface height.
        target.y = _aimer.WorldAimPoint.y;

        GameObject go = Instantiate(_thrownWrenchPrefab, CatchPoint, Quaternion.identity);
        _airborne = go.GetComponent<ThrownWrench>();
        if (_airborne != null) _airborne.Launch(this, target, _config);
        else Destroy(go);
    }

    /// <summary>Called by ThrownWrench when it has returned and been caught.</summary>
    public void OnCaught() => _airborne = null;
}

using UnityEngine;
using UnityEngine.Events;

/// <summary>
/// Marks a world object as a harvestable resource and manages its runtime health.
/// Subscribes to <see cref="ResourceManager.OnResourceHit"/> so it only takes damage
/// when the player's hit targets this object (or a child collider). All static data
/// (required tool, max health, drops) lives in the assigned
/// <see cref="ResourceNodeConfig"/> ScriptableObject.
///
/// Designer-hookable events are exposed as UnityEvents in the Inspector:
///   • <see cref="OnHitEvent"/>      — after each hit that damages this node
///   • <see cref="OnDepletedEvent"/>  — when health reaches zero
///
/// AttackAnimIndex maps RequiredTool → Animator AttackIndex (1-4):
///   Pick = 1 | Axe = 2 | Hammer = 3 | Wrench = 4
/// </summary>
public class ResourceNode : MonoBehaviour
{
    // ── Inspector ─────────────────────────────────────────────────────────────

    [Tooltip("Data asset for this resource type (health, tool, drops). Create via Flynn/Resource/Node Config.")]
    [SerializeField] private ResourceNodeConfig _config;

    [Tooltip("Channel raised on each hit so the HUD can show a world-anchored HP bar. Optional.")]
    [SerializeField] private ResourceHitChannel _hitChannel;

    // ── UnityEvents (designer-hookable) ───────────────────────────────────────

    [Header("Events")]
    [Tooltip("Fired after each hit that damages this node. Argument = remaining health.")]
    [SerializeField] private IntEvent _onHitEvent = new IntEvent();

    [Tooltip("Fired when health reaches zero (before drops / destruction).")]
    [SerializeField] private UnityEvent _onDepletedEvent = new UnityEvent();

    // ── C# events (code-side subscribers) ─────────────────────────────────────

    /// <summary>Raised after each successful hit. Argument is remaining health.</summary>
    public event System.Action<int> OnDamaged;

    /// <summary>Raised when health reaches zero, before drops are spawned.</summary>
    public event System.Action OnDepleted;

    // ── Public properties ─────────────────────────────────────────────────────

    public ResourceNodeConfig Config => _config;

    /// <summary>Current remaining health this session.</summary>
    public int CurrentHealth { get; private set; }

    /// <summary>Maximum health from the config (1 when unconfigured).</summary>
    public int MaxHealth => _config != null ? Mathf.Max(1, _config.maxHealth) : 1;

    /// <summary>Remaining health as a 0-1 fraction.</summary>
    public float Health01 => Mathf.Clamp01((float)CurrentHealth / MaxHealth);

    private bool _depleted;

    /// <summary>Convenience accessor so callers don't have to null-check Config.</summary>
    public ItemType RequiredTool => _config != null ? _config.requiredTool : ItemType.Pick;

    /// <summary>Display label for hover UI.</summary>
    public string DisplayName => _config != null ? _config.displayName : "Resource";

    /// <summary>
    /// Animator AttackIndex value for this resource's required tool.
    /// Returns 0 when no valid tool is mapped.
    /// </summary>
    public int AttackAnimIndex => RequiredTool switch
    {
        ItemType.Pick   => 1,
        ItemType.Axe    => 2,
        ItemType.Hammer => 3,
        ItemType.Wrench => 4,
        _               => 0,
    };

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        CurrentHealth = _config != null ? _config.maxHealth : 1;
    }

    private void OnEnable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit += HandleResourceManagerHit;
    }

    private void OnDisable()
    {
        if (ResourceManager.Instance != null)
            ResourceManager.Instance.OnResourceHit -= HandleResourceManagerHit;
    }

    // ── Public API ────────────────────────────────────────────────────────────

    /// <summary>
    /// Apply <paramref name="damage"/> points to this node. When health reaches
    /// zero the node spawns its drops and destroys itself.
    /// </summary>
    /// <param name="damage">Positive integer damage value.</param>
    public void ReceiveHit(int damage)
    {
        if (CurrentHealth <= 0) return;

        CurrentHealth = Mathf.Max(0, CurrentHealth - damage);

        // C# event (code subscribers)
        OnDamaged?.Invoke(CurrentHealth);

        // UnityEvent (designer-hooked effects)
        _onHitEvent?.Invoke(CurrentHealth);

        // HUD channel
        if (_hitChannel != null) _hitChannel.Raise(this, Health01);

        if (CurrentHealth <= 0)
            Deplete();
    }

    // ── Private ───────────────────────────────────────────────────────────────

    /// <summary>
    /// Listener for <see cref="ResourceManager.OnResourceHit"/>. Only applies
    /// damage when the hit targets this object (or a child collider).
    /// </summary>
    private void HandleResourceManagerHit(PlayerHitInfo info)
    {
        if (info.Target == null) return;
        if (!IsThisResource(info.Target)) return;
        ReceiveHit(info.Power);
    }

    /// <summary>True if the target GameObject is this object or a descendant.</summary>
    private bool IsThisResource(GameObject target)
    {
        Transform t = target.transform;
        while (t != null)
        {
            if (t.gameObject == gameObject) return true;
            t = t.parent;
        }
        return false;
    }

    /// <summary>
    /// Node is exhausted. Raises events for the drop-spawner and death-fall
    /// listeners to react (eject drops, topple + fade). The node only destroys
    /// itself here as a fallback when no <see cref="ResourceDeathFall"/> is present
    /// to own the removal.
    /// </summary>
    private void Deplete()
    {
        if (_depleted) return;
        _depleted = true;

        // C# event (code subscribers)
        OnDepleted?.Invoke();

        // UnityEvent (designer-hooked effects)
        _onDepletedEvent?.Invoke();

        if (GetComponent<ResourceDeathFall>() == null)
            Destroy(gameObject);
    }

    // ── Nested types ──────────────────────────────────────────────────────────

    /// <summary>UnityEvent passing remaining health as an int.</summary>
    [System.Serializable]
    public class IntEvent : UnityEvent<int> { }
}

using System;
using UnityEngine;

/// <summary>
/// In-scene hub for resource events. A singleton so any script can reach it without Inspector
/// wiring: publishers call <see cref="RaiseHit"/>, subscribers do <c>OnResourceHit += ...</c> on
/// startup. The player and resources only ever know this manager — never each other.
///
/// For now it relays a single event (player hit). Add more events here as the resource layer grows;
/// the wiring pattern stays the same.
///
/// One per scene. Runs early (negative execution order) so <see cref="Instance"/> exists before any
/// subscriber's OnEnable runs.
/// </summary>
[DefaultExecutionOrder(-100)]
public class ResourceManager : MonoBehaviour
{
    public static ResourceManager Instance { get; private set; }

    [Tooltip("Log each raised hit. Off for production.")]
    [SerializeField] private bool _debugLog = true;

    /// <summary>Raised whenever a player hit lands. Subscribe with += on startup; unsubscribe with -=.</summary>
    public event Action<PlayerHitInfo> OnResourceHit;

    /// <summary>Publisher entry point: fire the hit event for all subscribers.</summary>
    public void RaiseHit(in PlayerHitInfo info)
    {
        if (_debugLog) Debug.Log($"[ResourceManager] hit @ {info.Point} target={(info.Target ? info.Target.name : "none")}");
        OnResourceHit?.Invoke(info);
    }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[ResourceManager] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }
}

using System;
using UnityEngine;

/// <summary>
/// Owns the runtime inventory state (copied from <see cref="InventoryData"/> on Awake — the SO
/// itself is never mutated at runtime). Holds a flat array of <see cref="InventorySlot"/>s:
/// slot 0 is the wrench slot, slots 1..N are general item slots that stack identical items up to
/// <see cref="ItemDefinition.maxStack"/>. The slot count is data-driven and extendable.
///
/// Accepts any item kind (resources, future tools, etc.). Currency items never enter a slot —
/// they route to their <see cref="ItemDefinition.currencyTarget"/> at the collection site.
/// Handles hotkey input (1-4) to switch the active slot; raises events for the HUD.
///
/// Acts as the game's inventory manager: a singleton (<see cref="Instance"/>) so the HUD, pickup,
/// drop, magnets and the wrench controllers all reach inventory through one access point and
/// subscribe to its events — no FindObjectOfType, no per-system GetComponent. Single-player, so one
/// instance is assumed. Runs early (negative execution order) so <see cref="Instance"/> exists
/// before any subscriber's Awake/OnEnable.
///
/// Pure manager — holds no scene-position state and never touches the character controller, so it
/// lives on a dedicated manager GameObject (e.g. MANAGERS/INVENTORY), not on the Player. All users
/// reach it through <see cref="Instance"/>; nothing requires it to share the Player's GameObject.
/// </summary>
[DefaultExecutionOrder(-50)]
public class PlayerInventory : MonoBehaviour
{
    /// <summary>The active inventory manager. Set in Awake, cleared on destroy.</summary>
    public static PlayerInventory Instance { get; private set; }

    public const int WrenchSlot = 0;

    [SerializeField] private InventoryData _inventoryConfig;

    public event Action<int> OnSlotChanged;
    public event Action<int> OnActiveSlotChanged;

    private InventorySlot[] _runtimeSlots = Array.Empty<InventorySlot>();
    private int _activeSlot;

    // ── Public API ────────────────────────────────────────────────────────────

    public int SlotCount => _runtimeSlots.Length;

    public int ActiveSlotIndex
    {
        get => _activeSlot;
        private set
        {
            int clamped = Mathf.Clamp(value, 0, SlotCount - 1);
            if (_activeSlot == clamped) return;
            _activeSlot = clamped;
            OnActiveSlotChanged?.Invoke(_activeSlot);
        }
    }

    public InventorySlot ActiveSlot => GetSlot(_activeSlot);
    public ItemDefinition ActiveItem => ActiveSlot.item;

    /// <summary>ItemType of the currently selected slot, or None if it's empty.</summary>
    public ItemType ActiveItemType => ActiveItem != null ? ActiveItem.itemType : ItemType.None;

    /// <summary>True when no general slot is empty (can't accept a new item kind).</summary>
    public bool IsFull
    {
        get
        {
            for (int i = 1; i < _runtimeSlots.Length; i++)
                if (_runtimeSlots[i].IsEmpty) return false;
            return true;
        }
    }

    public InventorySlot GetSlot(int index)
    {
        if (index < 0 || index >= _runtimeSlots.Length) return InventorySlot.Empty;
        return _runtimeSlots[index];
    }

    /// <summary>True if any slot currently holds an item of the given type.</summary>
    public bool HasItem(ItemType type)
    {
        for (int i = 0; i < _runtimeSlots.Length; i++)
            if (!_runtimeSlots[i].IsEmpty && _runtimeSlots[i].item.itemType == type) return true;
        return false;
    }

    /// <summary>
    /// True if at least one unit of <paramref name="item"/> can be accepted right now
    /// (a matching non-full stack, or an empty slot). Used by world-item magnets to decide
    /// whether to fly to the player or stay on the ground.
    /// </summary>
    public bool HasRoomFor(ItemDefinition item)
    {
        if (item == null || item.isCurrency) return false;

        if (item.itemType == ItemType.Wrench)
            return GetSlot(WrenchSlot).IsEmpty;

        for (int i = 1; i < _runtimeSlots.Length; i++)
        {
            if (_runtimeSlots[i].IsEmpty) return true;
            if (_runtimeSlots[i].item == item && !_runtimeSlots[i].IsFull) return true;
        }
        return false;
    }

    /// <summary>
    /// Add up to <paramref name="count"/> of <paramref name="item"/>, stacking into matching
    /// slots first then filling empty ones. Returns how many were actually added (0 = no room).
    /// Currency items are rejected here (they belong on the currency counter, not a slot).
    /// </summary>
    public int TryAddItem(ItemDefinition item, int count = 1)
    {
        if (item == null || count <= 0 || item.isCurrency) return 0;

        if (item.itemType == ItemType.Wrench)
        {
            if (!GetSlot(WrenchSlot).IsEmpty) return 0;
            _runtimeSlots[WrenchSlot] = InventorySlot.Of(item, 1);
            OnSlotChanged?.Invoke(WrenchSlot);
            return 1;
        }

        int added = 0;

        // 1) Top up existing matching stacks.
        for (int i = 1; i < _runtimeSlots.Length && added < count; i++)
        {
            if (_runtimeSlots[i].item != item || _runtimeSlots[i].IsFull) continue;
            int take = Mathf.Min(_runtimeSlots[i].SpaceLeft, count - added);
            _runtimeSlots[i].count += take;
            added += take;
            OnSlotChanged?.Invoke(i);
        }

        // 2) Fill empty slots.
        for (int i = 1; i < _runtimeSlots.Length && added < count; i++)
        {
            if (!_runtimeSlots[i].IsEmpty) continue;
            int take = Mathf.Min(Mathf.Max(1, item.maxStack), count - added);
            _runtimeSlots[i] = InventorySlot.Of(item, take);
            added += take;
            OnSlotChanged?.Invoke(i);
        }

        return added;
    }

    /// <summary>Remove one unit from a slot; returns the item removed, or null if the slot was empty.</summary>
    public ItemDefinition RemoveOne(int index) => RemoveFromSlot(index, 1, out _);

    /// <summary>Remove the whole stack from a slot; returns the item and (via out) how many were removed.</summary>
    public ItemDefinition RemoveStack(int index, out int removed)
        => RemoveFromSlot(index, int.MaxValue, out removed);

    /// <summary>Remove up to <paramref name="count"/> units from a slot.</summary>
    public ItemDefinition RemoveFromSlot(int index, int count, out int removed)
    {
        removed = 0;
        if (index < 0 || index >= _runtimeSlots.Length || count <= 0) return null;

        InventorySlot slot = _runtimeSlots[index];
        if (slot.IsEmpty) return null;

        ItemDefinition item = slot.item;
        removed = Mathf.Min(count, slot.count);
        slot.count -= removed;
        _runtimeSlots[index] = slot.count <= 0 ? InventorySlot.Empty : slot;
        OnSlotChanged?.Invoke(index);
        return item;
    }

    // ── Signals (inbound) ───────────────────────────────────────────────────────
    // Readability aliases over the API above. Same pattern as ResourceManager.RaiseHit:
    // a gameplay system "signals" the inventory (e.g. a pickup collision), the inventory
    // mutates its slots, then broadcasts OnSlotChanged / OnActiveSlotChanged outward.
    // The store is the one place that owns slot state — these just read like events.

    /// <summary>Signal: an item pickup was requested (e.g. by a collision/magnet). Returns how
    /// many units actually entered the inventory. Forwards to <see cref="TryAddItem"/>.</summary>
    public int SignalPickup(ItemDefinition item, int count = 1) => TryAddItem(item, count);

    /// <summary>Signal: drop one unit from a slot. Returns the item removed, or null if empty.
    /// Forwards to <see cref="RemoveOne"/>.</summary>
    public ItemDefinition SignalDropOne(int slot) => RemoveOne(slot);

    /// <summary>Signal: drop a whole stack from a slot. Forwards to <see cref="RemoveStack"/>.</summary>
    public ItemDefinition SignalDropStack(int slot, out int removed) => RemoveStack(slot, out removed);

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
            Debug.LogWarning($"[PlayerInventory] Second instance on '{name}'; overriding the previous Instance.", this);
        Instance = this;

        int count = _inventoryConfig != null ? _inventoryConfig.Slots : 4;
        _runtimeSlots = new InventorySlot[count];
        for (int i = 0; i < count; i++)
        {
            ItemDefinition def = _inventoryConfig != null ? _inventoryConfig.GetDefaultSlot(i) : null;
            _runtimeSlots[i] = def != null ? InventorySlot.Of(def, 1) : InventorySlot.Empty;
        }
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        ReadHotkeys();
    }

    // ── Private ───────────────────────────────────────────────────────────────

    private void ReadHotkeys()
    {
        if (Input.GetKeyDown(KeyCode.Alpha1))      ActiveSlotIndex = 0;
        else if (Input.GetKeyDown(KeyCode.Alpha2)) ActiveSlotIndex = 1;
        else if (Input.GetKeyDown(KeyCode.Alpha3)) ActiveSlotIndex = 2;
        else if (Input.GetKeyDown(KeyCode.Alpha4)) ActiveSlotIndex = 3;
    }
}

using UnityEngine;

/// <summary>
/// Picks up the key-pickup <see cref="WorldItem"/> the player is aiming at when the pickup key is
/// pressed: grants its item(s) to the inventory and removes it from the world. Only non-auto-collect
/// items (e.g. the wrench) need this — auto-collect drops fly to the player on their own.
/// Reads the hovered item from <see cref="PlayerMouseAimer"/>; writes to <see cref="PlayerInventory"/>.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerPickupController : MonoBehaviour
{
    [SerializeField] private KeyCode _pickupKey = KeyCode.E;

    private PlayerMouseAimer _aimer;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
    }

    private void Update()
    {
        if (!Input.GetKeyDown(_pickupKey)) return;

        WorldItem item = _aimer.HoveredKeyPickup;
        if (item == null || item.Item == null) return;

        PlayerInventory inv = PlayerInventory.Instance;
        if (inv == null) return;

        int added = inv.TryAddItem(item.Item, item.Count);
        if (added <= 0) return;

        if (added >= item.Count) Destroy(item.gameObject);
        else                     item.Reduce(added);
    }
}

using UnityEngine;

/// <summary>
/// Drops items from the inventory back into the world. <b>G</b> drops one unit of the active slot;
/// the HUD calls <see cref="DropSlot"/> to drop a whole stack via drag-off-the-bar. Dropped items
/// spawn through <see cref="WorldItemSpawner"/> and get a short re-collect delay so an auto-collecting
/// resource doesn't instantly fly back into the inventory.
/// </summary>
public class PlayerDropController : MonoBehaviour
{
    [SerializeField] private KeyCode _dropKey = KeyCode.G;
    [SerializeField] private float _dropForward = 0.8f;
    [SerializeField] private float _dropHeight = 0.6f;
    [SerializeField] private float _popImpulse = 2f;
    [Tooltip("Seconds before a dropped auto-collect item may fly back to the player.")]
    [SerializeField] private float _reCollectDelay = 1.5f;

    private static PlayerInventory Inv => PlayerInventory.Instance;

    private void Update()
    {
        if (Input.GetKeyDown(_dropKey) && Inv != null)
            DropFromSlot(Inv.ActiveSlotIndex, wholeStack: false);
    }

    /// <summary>Drop the entire stack in a slot (used by the hotbar drag-to-drop).</summary>
    public void DropSlot(int index) => DropFromSlot(index, wholeStack: true);

    private void DropFromSlot(int index, bool wholeStack)
    {
        if (Inv == null) return;
        InventorySlot slot = Inv.GetSlot(index);
        if (slot.IsEmpty) return;

        ItemDefinition item = slot.item;
        // No world prefab → can't represent it on the ground; abort rather than vanish the item.
        if (item == null || item.worldPrefab == null)
        {
            Debug.LogWarning($"[PlayerDropController] '{(item != null ? item.displayName : "null")}' has no worldPrefab; drop ignored.", this);
            return;
        }

        int count;
        if (wholeStack) Inv.RemoveStack(index, out count);
        else          { Inv.RemoveOne(index); count = 1; }

        if (item == null || count <= 0) return;

        Vector3 pos = transform.position + Vector3.up * _dropHeight + transform.forward * _dropForward;
        WorldItem dropped = WorldItemSpawner.Spawn(item, count, pos, _popImpulse);
        if (dropped != null)
        {
            DroppedItemMagnet magnet = dropped.GetComponent<DroppedItemMagnet>();
            if (magnet != null) magnet.Suppress(_reCollectDelay);
        }
    }
}

using UnityEngine;

/// <summary>
/// The single droppable / pickupable unit in the world: an <see cref="ItemDefinition"/> plus a
/// stack count. Everything that can sit on the ground — resource drops, echo shards, the wrench,
/// items dropped from the inventory — is a WorldItem. Auto-collecting items are pulled in by
/// <see cref="DroppedItemMagnet"/>; non-auto items (the wrench) are picked up with the pickup key
/// via <see cref="PlayerMouseAimer"/>/<see cref="PlayerPickupController"/>.
///
/// Detection is by mouse raycast (solid, non-trigger collider on the pickup layer) — no registry.
/// </summary>
[RequireComponent(typeof(Collider))]
public class WorldItem : MonoBehaviour, IInteractionPromptProvider
{
    [Tooltip("Item this world object represents.")]
    [SerializeField] private ItemDefinition _item;

    [Tooltip("How many of the item this stack holds.")]
    [SerializeField] private int _count = 1;

    public ItemDefinition Item => _item;
    public int Count => _count;

    /// <summary>Set the item + count, e.g. when spawned by <see cref="WorldItemSpawner"/>.</summary>
    public void Configure(ItemDefinition item, int count)
    {
        _item = item;
        _count = Mathf.Max(1, count);
    }

    /// <summary>Reduce the stack after a partial collection; returns the remaining count.</summary>
    public int Reduce(int amount)
    {
        _count = Mathf.Max(0, _count - Mathf.Max(0, amount));
        return _count;
    }

    // Only key-pickup items prompt; auto-collect drops fly in on their own (no prompt).
    public bool TryGetPrompt(out InteractionPrompt prompt)
    {
        if (_item == null || _item.AutoCollects)
        {
            prompt = default;
            return false;
        }
        prompt = new InteractionPrompt("E", "Pick Up", transform, _item.displayName);
        return true;
    }
}

using UnityEngine;

/// <summary>
/// Pulls an auto-collecting <see cref="WorldItem"/> to the player after a short settle delay, then
/// collects it: resources/items go to the inventory, currencies to their counter. If the inventory
/// has no room the item idles on the ground and re-checks periodically (VS-style gem behaviour).
///
/// Finds the player through a <see cref="PlayerAnchor"/> SO — no FindObjectOfType. Non-auto items
/// (the wrench) disable this component and are picked up with the pickup key instead.
/// </summary>
[RequireComponent(typeof(WorldItem))]
public class DroppedItemMagnet : MonoBehaviour
{
    [SerializeField] private PlayerAnchor _playerAnchor;

    [Header("Timing")]
    [Tooltip("Seconds the drop sits/settles before it may fly to the player.")]
    [SerializeField] private float _settleDelay = 0.6f;
    [Tooltip("How often to re-check for inventory room while waiting.")]
    [SerializeField] private float _roomRecheckInterval = 0.4f;

    [Header("Flight")]
    [SerializeField] private float _maxSpeed = 7f;
    [SerializeField] private float _acceleration = 16f;
    [SerializeField] private float _collectRadius = 0.55f;
    [SerializeField] private float _targetHeight = 0.6f;

    private WorldItem _item;
    private Rigidbody _rb;

    private float _age;
    private float _extraDelay;
    private float _recheckTimer;
    private float _speed;
    private bool _flying;

    /// <summary>
    /// Delay auto-collection by <paramref name="seconds"/> beyond the normal settle (used when the
    /// player drops an item so it doesn't instantly fly back). Takes the longer of any pending delay.
    /// </summary>
    public void Suppress(float seconds)
    {
        _extraDelay = Mathf.Max(_extraDelay, seconds);
        _flying = false;
    }

    private void Awake()
    {
        _item = GetComponent<WorldItem>();
        _rb = GetComponent<Rigidbody>();
    }

    private void OnEnable()
    {
        _age = 0f;
        _extraDelay = 0f;
        _recheckTimer = 0f;
        _speed = 0f;
        _flying = false;
    }

    private void Update()
    {
        ItemDefinition def = _item != null ? _item.Item : null;
        if (def == null) return;

        // Non-auto items (wrench) wait for the pickup key — not our job.
        if (!def.AutoCollects) { enabled = false; return; }

        _age += Time.deltaTime;
        if (_age < _settleDelay + _extraDelay) return;

        Transform player = _playerAnchor != null ? _playerAnchor.Current : null;
        if (player == null) return;

        if (!_flying)
        {
            _recheckTimer -= Time.deltaTime;
            if (_recheckTimer > 0f) return;
            _recheckTimer = _roomRecheckInterval;
            if (!HasRoom(def, player)) return;
            BeginFlight();
        }

        _speed = Mathf.MoveTowards(_speed, _maxSpeed, _acceleration * Time.deltaTime);
        Vector3 target = player.position + Vector3.up * _targetHeight;
        transform.position = Vector3.MoveTowards(transform.position, target, _speed * Time.deltaTime);

        if (Vector3.Distance(transform.position, target) <= _collectRadius)
            Collect(def, player);
    }

    private bool HasRoom(ItemDefinition def, Transform player)
    {
        if (def.isCurrency) return true;
        return PlayerInventory.Instance != null && PlayerInventory.Instance.HasRoomFor(def);
    }

    private void BeginFlight()
    {
        _flying = true;
        if (_rb != null)
        {
            _rb.velocity = Vector3.zero;
            _rb.angularVelocity = Vector3.zero;
            _rb.isKinematic = true; // hand control to the magnet's MoveTowards
        }
    }

    private void Collect(ItemDefinition def, Transform player)
    {
        if (def.isCurrency)
        {
            if (def.currencyTarget != null) def.currencyTarget.Add(_item.Count);
            Destroy(gameObject);
            return;
        }

        int added = PlayerInventory.Instance != null ? PlayerInventory.Instance.TryAddItem(def, _item.Count) : 0;
        if (added >= _item.Count)
        {
            Destroy(gameObject);
            return;
        }

        // Inventory filled mid-flight: drop the remainder back on the ground and idle.
        if (added > 0) _item.Reduce(added);
        _flying = false;
        _speed = 0f;
        if (_rb != null) _rb.isKinematic = false;
    }
}

using UnityEngine;

/// <summary>
/// Stub robot energy system. Owns a 0–100 <see cref="IntVariable"/> battery and ticks it down over
/// time; exposes charge/drain API. The HUD reads the battery purely through
/// <see cref="IntVariable.OnChanged"/> — same hub pattern as the other managers (this writes the
/// value, listeners react). Replace the passive-drain placeholder with real costs (actions, tools,
/// time-of-day) when the energy economy is designed.
///
/// One per scene; lives on a manager GameObject (e.g. MANAGERS/BATTERY).
/// </summary>
[DefaultExecutionOrder(-40)]
public class RobotBattery : MonoBehaviour
{
    public const int Min = 0;
    public const int Max = 100;

    public static RobotBattery Instance { get; private set; }

    [Tooltip("The shared 0–100 battery value the HUD displays. Assign the same asset on PlayerHudPanel.")]
    [SerializeField] private IntVariable _battery;

    [SerializeField, Range(Min, Max)] private int _startCharge = 100;

    [Tooltip("Passive drain in battery points per second. 0 = no auto-drain (placeholder economy).")]
    [SerializeField] private float _drainPerSecond = 1f;

    [SerializeField] private bool _autoDrain = true;

    private float _accum;

    // ── API ──────────────────────────────────────────────────────────────────

    public int Charge => _battery != null ? _battery.Value : 0;
    public bool IsEmpty => Charge <= Min;
    public bool IsFull  => Charge >= Max;

    /// <summary>Add charge (negative to drain). Clamped to 0–100; notifies via the IntVariable.</summary>
    public void AddCharge(int amount) => SetCharge(Charge + amount);

    /// <summary>Drain charge by a positive amount.</summary>
    public void Drain(int amount) => SetCharge(Charge - Mathf.Abs(amount));

    public void SetCharge(int value)
    {
        if (_battery == null) return;
        _battery.Value = Mathf.Clamp(value, Min, Max);
    }

    public void SetAutoDrain(bool on) => _autoDrain = on;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[RobotBattery] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        SetCharge(_startCharge);
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (!_autoDrain || _drainPerSecond <= 0f || _battery == null || IsEmpty) return;

        _accum += _drainPerSecond * Time.deltaTime;
        if (_accum < 1f) return;

        int whole = Mathf.FloorToInt(_accum);
        _accum -= whole;
        Drain(whole);
    }
}

using UnityEngine;

/// <summary>The kind of terrain interaction a <see cref="TerrainEffectZone"/> applies.</summary>
public enum TerrainEffectType { Wind, Water, Mud, Ice }

/// <summary>
/// A trigger volume that applies one terrain effect to bodies inside it, composing with the
/// force-based <see cref="SolarpunkCharacterController"/>:
/// - Wind: AddForce each step (affects the player AND light pushable blocks).
/// - Water: lowers the player's target speed (SpeedMultiplier) — noticeable slow.
/// - Mud: lowers target speed AND blocks jumping while grounded on it.
/// - Ice: lowers steering authority (SteeringControl) so momentum carries and direction is
///   hard to change; paired with a frictionless PhysicMaterial on the ice surface. Never 0,
///   so the player can always work their way off the ice (no soft-lock).
/// Single-responsibility: one zone, one configured effect. No statics, no Find.
/// </summary>
[RequireComponent(typeof(Collider))]
public class TerrainEffectZone : MonoBehaviour
{
    [SerializeField] private TerrainEffectType type = TerrainEffectType.Wind;

    [Header("Wind")]
    [Tooltip("World-space force applied to each Rigidbody inside, every physics step. Large values blow the player back far.")]
    [SerializeField] private Vector3 windForce = new Vector3(60f, 0f, 0f);

    [Header("Water / Mud")]
    [Tooltip("Target-speed multiplier applied to the player while inside (lower = slower).")]
    [Range(0f, 1f)]
    [SerializeField] private float speedMultiplier = 0.4f;

    [Header("Ice / Wind steering")]
    [Tooltip("Steering-force multiplier while inside. Ice low = slidey; Wind low = controller stops fighting the wind so it blows you. Kept > 0 so the player can always escape.")]
    [Range(0.02f, 1f)]
    [SerializeField] private float steeringControl = 0.15f;

    private void Reset()
    {
        var c = GetComponent<Collider>();
        if (c != null) c.isTrigger = true;
    }

    private void OnTriggerStay(Collider other)
    {
        var rb = other.attachedRigidbody;
        if (rb == null) return;

        if (type == TerrainEffectType.Wind)
            rb.AddForce(windForce, ForceMode.Force); // pushes the player AND light blocks

        var pc = rb.GetComponent<SolarpunkCharacterController>();
        if (pc == null) return;

        switch (type)
        {
            case TerrainEffectType.Wind:
                pc.SteeringControl = steeringControl; // weaken self-correction so wind blows the player
                break;
            case TerrainEffectType.Water:
                pc.SpeedMultiplier = speedMultiplier;
                break;
            case TerrainEffectType.Mud:
                pc.SpeedMultiplier = speedMultiplier;
                if (pc.IsGrounded) pc.CanJump = false;
                break;
            case TerrainEffectType.Ice:
                pc.SteeringControl = steeringControl;
                pc.LowGrip = true; // glide: no braking when idle, momentum carries
                break;
        }
    }
}

using UnityEngine;

// 2.5D force-based character controller. Moves on the XZ plane via acceleration
// toward a target velocity, so Unity physics drives interactions: PhysicMaterial
// friction (ice/mud), Rigidbody.drag (water), and AddForce zones (wind) all
// compose naturally instead of being overwritten. Small jump impulse, gravity
// handled by the Rigidbody.
[RequireComponent(typeof(Rigidbody))]
public class SolarpunkCharacterController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;        // target horizontal speed under input
    [SerializeField] private float acceleration = 40f;    // how hard we drive toward target
    [SerializeField] private float jumpForce = 6f;
    // Baseline drag is 0: accel-to-target already arrests horizontal motion when input is
    // released (target velocity 0 -> decel force), so we need no passive drag — and drag is
    // isotropic, which would damp jump/fall. Water zones raise this temporarily; ice keeps it low.
    [SerializeField] private float groundDrag = 0f;
    [SerializeField] private float groundCheckDistance = 0.12f;
    [SerializeField] private LayerMask groundLayers = ~0;
    // Ice low-grip is re-asserted by the zone every physics step. Latch it for a short grace
    // window so a single missed OnTriggerStay (e.g. player center crossing the trigger edge
    // while the capsule is still on the ice) doesn't snap the ground brake back on for a step
    // and bleed the slide. Grace ends well before the player is truly off the ice.
    [SerializeField] private float lowGripGrace = 0.2f;

    public Vector3 MoveInput => moveInput;
    public bool IsGrounded => isGrounded;
    /// <summary>Horizontal speed normalized 0-1 relative to moveSpeed.</summary>
    public float NormalizedSpeed => rb != null
        ? Mathf.Clamp01(new Vector2(rb.velocity.x, rb.velocity.z).magnitude / moveSpeed)
        : 0f;

    /// <summary>Multiplies steering force each physics step. Ice sets this low (slidey, weak
    /// steering, momentum dominates) — kept &gt;0 so the player can always escape ice. Auto-resets to 1.</summary>
    public float SteeringControl { get; set; } = 1f;

    /// <summary>Multiplies the target move speed each physics step. Water/Mud set this below 1 to
    /// slow the player noticeably (lowering the target, since drag/friction barely dents accel-to-target).
    /// Auto-resets to 1.</summary>
    public float SpeedMultiplier { get; set; } = 1f;

    /// <summary>Set false each physics step by a mud zone while grounded on it: blocks jumping
    /// ("mud stops vertical movement"). Auto-resets to true.</summary>
    public bool CanJump { get; set; } = true;

    /// <summary>Set true each physics step by an ice zone: the controller stops braking toward
    /// zero when there's no input, so momentum carries (glide). Steering still applies (scaled by
    /// SteeringControl) so the player can nudge off the ice. Auto-resets to false.</summary>
    public bool LowGrip { get; set; } = false;

    public Vector3 RbVelocityDirection { get; private set; }

    private Rigidbody rb;
    private Collider bodyCollider;
    private bool isGrounded;
    private Vector3 moveInput;
    private bool jumpQueued;
    private float lowGripTimer;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        bodyCollider = GetComponent<Collider>();
        rb.drag = groundDrag;
        rb.freezeRotation = true;
    }

    private void Update()
    {
        moveInput.x = Input.GetAxisRaw("Horizontal");
        moveInput.z = Input.GetAxisRaw("Vertical");
        RbVelocityDirection = rb.velocity.normalized;
        if (moveInput.sqrMagnitude > 1f) moveInput.Normalize();

        if (Input.GetButtonDown("Jump")) jumpQueued = true;
    }



    private void FixedUpdate()
    {
        UpdateGrounded();

        // Accelerate toward the input-driven target velocity (XZ only). External forces
        // (wind AddForce) and surface friction are left to the solver. SpeedMultiplier
        // lowers the target (water/mud slow); SteeringControl scales the force (ice = slidey,
        // weak steering so momentum carries, but never 0 so the player can't get stuck).
        Vector3 horizVel = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
        Vector3 inputDir = new Vector3(moveInput.x, 0f, moveInput.z);
        bool idle = inputDir.sqrMagnitude < 0.01f;
        // Latch low-grip: refresh the timer while the zone asserts it, otherwise decay it.
        // The brake stays off for the whole grace window, surviving single-step trigger gaps.
        if (LowGrip) lowGripTimer = lowGripGrace;
        else lowGripTimer -= Time.fixedDeltaTime;
        bool lowGrip = lowGripTimer > 0f;
        if (lowGrip)
        {
            // Ice: momentum carries, input only steers. With input, push in the input direction
            // WITHOUT the "- horizVel" brake term (that term is what kills the slide on normal
            // ground), so existing momentum is preserved and the velocity vector rotates toward
            // the input instead of being reset to it. Speed is capped to moveSpeed so the additive
            // force can't run away. Idle = no force, the frictionless surface keeps the glide.
            if (!idle)
            {
                rb.AddForce(inputDir * moveSpeed * acceleration * SteeringControl, ForceMode.Acceleration);
                Vector3 hv = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
                float maxSpeed = moveSpeed * SpeedMultiplier;
                if (hv.magnitude > maxSpeed)
                {
                    hv = hv.normalized * maxSpeed;
                    rb.velocity = new Vector3(hv.x, rb.velocity.y, hv.z);
                }
            }
        }
        else
        {
            // Normal ground: accelerate toward the input-driven target velocity (XZ only).
            // SpeedMultiplier lowers the target (water/mud slow); SteeringControl scales the
            // force (wind = weak self-correction so wind blows you).
            Vector3 targetVel = inputDir * moveSpeed * SpeedMultiplier;
            Vector3 dv = targetVel - horizVel;
            rb.AddForce(dv * acceleration * SteeringControl, ForceMode.Acceleration);
        }

        if (jumpQueued && isGrounded && CanJump)
        {
            Vector3 v = rb.velocity; v.y = 0f; rb.velocity = v;
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
            isGrounded = false;
        }
        jumpQueued = false;

        // Per-step terrain modifiers; zones re-assert them in OnTriggerStay (which fires
        // after FixedUpdate within the same physics step).
        SteeringControl = 1f;
        SpeedMultiplier = 1f;
        CanJump = true;
        LowGrip = false;
    }

    private void UpdateGrounded()
    {
        if (bodyCollider == null)
        {
            isGrounded = false;
            return;
        }

        Vector3 origin = bodyCollider.bounds.center;
        origin.y = bodyCollider.bounds.min.y + 0.02f;

        isGrounded = Physics.Raycast(
            origin,
            Vector3.down,
            groundCheckDistance,
            groundLayers,
            QueryTriggerInteraction.Ignore
        );
    }
}

using UnityEngine;

/// <summary>
/// Drops items from the inventory back into the world. <b>G</b> drops one unit of the active slot;
/// the HUD calls <see cref="DropSlot"/> to drop a whole stack via drag-off-the-bar. Dropped items
/// spawn through <see cref="WorldItemSpawner"/> and get a short re-collect delay so an auto-collecting
/// resource doesn't instantly fly back into the inventory.
/// </summary>
public class PlayerDropController : MonoBehaviour
{
    [SerializeField] private KeyCode _dropKey = KeyCode.G;
    [SerializeField] private float _dropForward = 0.8f;
    [SerializeField] private float _dropHeight = 0.6f;
    [SerializeField] private float _popImpulse = 2f;
    [Tooltip("Seconds before a dropped auto-collect item may fly back to the player.")]
    [SerializeField] private float _reCollectDelay = 1.5f;

    private static PlayerInventory Inv => PlayerInventory.Instance;

    private void Update()
    {
        if (Input.GetKeyDown(_dropKey) && Inv != null)
            DropFromSlot(Inv.ActiveSlotIndex, wholeStack: false);
    }

    /// <summary>Drop the entire stack in a slot (used by the hotbar drag-to-drop).</summary>
    public void DropSlot(int index) => DropFromSlot(index, wholeStack: true);

    private void DropFromSlot(int index, bool wholeStack)
    {
        if (Inv == null) return;
        InventorySlot slot = Inv.GetSlot(index);
        if (slot.IsEmpty) return;

        ItemDefinition item = slot.item;
        // No world prefab → can't represent it on the ground; abort rather than vanish the item.
        if (item == null || item.worldPrefab == null)
        {
            Debug.LogWarning($"[PlayerDropController] '{(item != null ? item.displayName : "null")}' has no worldPrefab; drop ignored.", this);
            return;
        }

        int count;
        if (wholeStack) Inv.RemoveStack(index, out count);
        else          { Inv.RemoveOne(index); count = 1; }

        if (item == null || count <= 0) return;

        Vector3 pos = transform.position + Vector3.up * _dropHeight + transform.forward * _dropForward;
        WorldItem dropped = WorldItemSpawner.Spawn(item, count, pos, _popImpulse);
        if (dropped != null)
        {
            DroppedItemMagnet magnet = dropped.GetComponent<DroppedItemMagnet>();
            if (magnet != null) magnet.Suppress(_reCollectDelay);
        }
    }
}

using UnityEngine;

/// <summary>
/// The single droppable / pickupable unit in the world: an <see cref="ItemDefinition"/> plus a
/// stack count. Everything that can sit on the ground — resource drops, echo shards, the wrench,
/// items dropped from the inventory — is a WorldItem. Auto-collecting items are pulled in by
/// <see cref="DroppedItemMagnet"/>; non-auto items (the wrench) are picked up with the pickup key
/// via <see cref="PlayerMouseAimer"/>/<see cref="PlayerPickupController"/>.
///
/// Detection is by mouse raycast (solid, non-trigger collider on the pickup layer) — no registry.
/// </summary>
[RequireComponent(typeof(Collider))]
public class WorldItem : MonoBehaviour, IInteractionPromptProvider
{
    [Tooltip("Item this world object represents.")]
    [SerializeField] private ItemDefinition _item;

    [Tooltip("How many of the item this stack holds.")]
    [SerializeField] private int _count = 1;

    public ItemDefinition Item => _item;
    public int Count => _count;

    /// <summary>Set the item + count, e.g. when spawned by <see cref="WorldItemSpawner"/>.</summary>
    public void Configure(ItemDefinition item, int count)
    {
        _item = item;
        _count = Mathf.Max(1, count);
    }

    /// <summary>Reduce the stack after a partial collection; returns the remaining count.</summary>
    public int Reduce(int amount)
    {
        _count = Mathf.Max(0, _count - Mathf.Max(0, amount));
        return _count;
    }

    // Only key-pickup items prompt; auto-collect drops fly in on their own (no prompt).
    public bool TryGetPrompt(out InteractionPrompt prompt)
    {
        if (_item == null || _item.AutoCollects)
        {
            prompt = default;
            return false;
        }
        prompt = new InteractionPrompt("E", "Pick Up", transform, _item.displayName);
        return true;
    }
}

using UnityEngine;

/// <summary>
/// Pulls an auto-collecting <see cref="WorldItem"/> to the player after a short settle delay, then
/// collects it: resources/items go to the inventory, currencies to their counter. If the inventory
/// has no room the item idles on the ground and re-checks periodically (VS-style gem behaviour).
///
/// Finds the player through a <see cref="PlayerAnchor"/> SO — no FindObjectOfType. Non-auto items
/// (the wrench) disable this component and are picked up with the pickup key instead.
/// </summary>
[RequireComponent(typeof(WorldItem))]
public class DroppedItemMagnet : MonoBehaviour
{
    [SerializeField] private PlayerAnchor _playerAnchor;

    [Header("Timing")]
    [Tooltip("Seconds the drop sits/settles before it may fly to the player.")]
    [SerializeField] private float _settleDelay = 0.6f;
    [Tooltip("How often to re-check for inventory room while waiting.")]
    [SerializeField] private float _roomRecheckInterval = 0.4f;

    [Header("Flight")]
    [SerializeField] private float _maxSpeed = 7f;
    [SerializeField] private float _acceleration = 16f;
    [SerializeField] private float _collectRadius = 0.55f;
    [SerializeField] private float _targetHeight = 0.6f;

    private WorldItem _item;
    private Rigidbody _rb;

    private float _age;
    private float _extraDelay;
    private float _recheckTimer;
    private float _speed;
    private bool _flying;

    /// <summary>
    /// Delay auto-collection by <paramref name="seconds"/> beyond the normal settle (used when the
    /// player drops an item so it doesn't instantly fly back). Takes the longer of any pending delay.
    /// </summary>
    public void Suppress(float seconds)
    {
        _extraDelay = Mathf.Max(_extraDelay, seconds);
        _flying = false;
    }

    private void Awake()
    {
        _item = GetComponent<WorldItem>();
        _rb = GetComponent<Rigidbody>();
    }

    private void OnEnable()
    {
        _age = 0f;
        _extraDelay = 0f;
        _recheckTimer = 0f;
        _speed = 0f;
        _flying = false;
    }

    private void Update()
    {
        ItemDefinition def = _item != null ? _item.Item : null;
        if (def == null) return;

        // Non-auto items (wrench) wait for the pickup key — not our job.
        if (!def.AutoCollects) { enabled = false; return; }

        _age += Time.deltaTime;
        if (_age < _settleDelay + _extraDelay) return;

        Transform player = _playerAnchor != null ? _playerAnchor.Current : null;
        if (player == null) return;

        if (!_flying)
        {
            _recheckTimer -= Time.deltaTime;
            if (_recheckTimer > 0f) return;
            _recheckTimer = _roomRecheckInterval;
            if (!HasRoom(def, player)) return;
            BeginFlight();
        }

        _speed = Mathf.MoveTowards(_speed, _maxSpeed, _acceleration * Time.deltaTime);
        Vector3 target = player.position + Vector3.up * _targetHeight;
        transform.position = Vector3.MoveTowards(transform.position, target, _speed * Time.deltaTime);

        if (Vector3.Distance(transform.position, target) <= _collectRadius)
            Collect(def, player);
    }

    private bool HasRoom(ItemDefinition def, Transform player)
    {
        if (def.isCurrency) return true;
        return PlayerInventory.Instance != null && PlayerInventory.Instance.HasRoomFor(def);
    }

    private void BeginFlight()
    {
        _flying = true;
        if (_rb != null)
        {
            _rb.velocity = Vector3.zero;
            _rb.angularVelocity = Vector3.zero;
            _rb.isKinematic = true; // hand control to the magnet's MoveTowards
        }
    }

    private void Collect(ItemDefinition def, Transform player)
    {
        if (def.isCurrency)
        {
            if (def.currencyTarget != null) def.currencyTarget.Add(_item.Count);
            Destroy(gameObject);
            return;
        }

        int added = PlayerInventory.Instance != null ? PlayerInventory.Instance.TryAddItem(def, _item.Count) : 0;
        if (added >= _item.Count)
        {
            Destroy(gameObject);
            return;
        }

        // Inventory filled mid-flight: drop the remainder back on the ground and idle.
        if (added > 0) _item.Reduce(added);
        _flying = false;
        _speed = 0f;
        if (_rb != null) _rb.isKinematic = false;
    }
}

using UnityEngine;

/// <summary>
/// Stub robot energy system. Owns a 0–100 <see cref="IntVariable"/> battery and ticks it down over
/// time; exposes charge/drain API. The HUD reads the battery purely through
/// <see cref="IntVariable.OnChanged"/> — same hub pattern as the other managers (this writes the
/// value, listeners react). Replace the passive-drain placeholder with real costs (actions, tools,
/// time-of-day) when the energy economy is designed.
///
/// One per scene; lives on a manager GameObject (e.g. MANAGERS/BATTERY).
/// </summary>
[DefaultExecutionOrder(-40)]
public class RobotBattery : MonoBehaviour
{
    public const int Min = 0;
    public const int Max = 100;

    public static RobotBattery Instance { get; private set; }

    [Tooltip("The shared 0–100 battery value the HUD displays. Assign the same asset on PlayerHudPanel.")]
    [SerializeField] private IntVariable _battery;

    [SerializeField, Range(Min, Max)] private int _startCharge = 100;

    [Tooltip("Passive drain in battery points per second. 0 = no auto-drain (placeholder economy).")]
    [SerializeField] private float _drainPerSecond = 1f;

    [SerializeField] private bool _autoDrain = true;

    private float _accum;

    // ── API ──────────────────────────────────────────────────────────────────

    public int Charge => _battery != null ? _battery.Value : 0;
    public bool IsEmpty => Charge <= Min;
    public bool IsFull  => Charge >= Max;

    /// <summary>Add charge (negative to drain). Clamped to 0–100; notifies via the IntVariable.</summary>
    public void AddCharge(int amount) => SetCharge(Charge + amount);

    /// <summary>Drain charge by a positive amount.</summary>
    public void Drain(int amount) => SetCharge(Charge - Mathf.Abs(amount));

    public void SetCharge(int value)
    {
        if (_battery == null) return;
        _battery.Value = Mathf.Clamp(value, Min, Max);
    }

    public void SetAutoDrain(bool on) => _autoDrain = on;

    // ── Unity messages ────────────────────────────────────────────────────────

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Debug.LogWarning($"[RobotBattery] Duplicate; destroying {name}.", this);
            Destroy(this);
            return;
        }
        Instance = this;
        SetCharge(_startCharge);
    }

    private void OnDestroy()
    {
        if (Instance == this) Instance = null;
    }

    private void Update()
    {
        if (!_autoDrain || _drainPerSecond <= 0f || _battery == null || IsEmpty) return;

        _accum += _drainPerSecond * Time.deltaTime;
        if (_accum < 1f) return;

        int whole = Mathf.FloorToInt(_accum);
        _accum -= whole;
        Drain(whole);
    }
}

using UnityEngine;

/// <summary>The kind of terrain interaction a <see cref="TerrainEffectZone"/> applies.</summary>
public enum TerrainEffectType { Wind, Water, Mud, Ice }

/// <summary>
/// A trigger volume that applies one terrain effect to bodies inside it, composing with the
/// force-based <see cref="SolarpunkCharacterController"/>:
/// - Wind: AddForce each step (affects the player AND light pushable blocks).
/// - Water: lowers the player's target speed (SpeedMultiplier) — noticeable slow.
/// - Mud: lowers target speed AND blocks jumping while grounded on it.
/// - Ice: lowers steering authority (SteeringControl) so momentum carries and direction is
///   hard to change; paired with a frictionless PhysicMaterial on the ice surface. Never 0,
///   so the player can always work their way off the ice (no soft-lock).
/// Single-responsibility: one zone, one configured effect. No statics, no Find.
/// </summary>
[RequireComponent(typeof(Collider))]
public class TerrainEffectZone : MonoBehaviour
{
    [SerializeField] private TerrainEffectType type = TerrainEffectType.Wind;

    [Header("Wind")]
    [Tooltip("World-space force applied to each Rigidbody inside, every physics step. Large values blow the player back far.")]
    [SerializeField] private Vector3 windForce = new Vector3(60f, 0f, 0f);

    [Header("Water / Mud")]
    [Tooltip("Target-speed multiplier applied to the player while inside (lower = slower).")]
    [Range(0f, 1f)]
    [SerializeField] private float speedMultiplier = 0.4f;

    [Header("Ice / Wind steering")]
    [Tooltip("Steering-force multiplier while inside. Ice low = slidey; Wind low = controller stops fighting the wind so it blows you. Kept > 0 so the player can always escape.")]
    [Range(0.02f, 1f)]
    [SerializeField] private float steeringControl = 0.15f;

    private void Reset()
    {
        var c = GetComponent<Collider>();
        if (c != null) c.isTrigger = true;
    }

    private void OnTriggerStay(Collider other)
    {
        var rb = other.attachedRigidbody;
        if (rb == null) return;

        if (type == TerrainEffectType.Wind)
            rb.AddForce(windForce, ForceMode.Force); // pushes the player AND light blocks

        var pc = rb.GetComponent<SolarpunkCharacterController>();
        if (pc == null) return;

        switch (type)
        {
            case TerrainEffectType.Wind:
                pc.SteeringControl = steeringControl; // weaken self-correction so wind blows the player
                break;
            case TerrainEffectType.Water:
                pc.SpeedMultiplier = speedMultiplier;
                break;
            case TerrainEffectType.Mud:
                pc.SpeedMultiplier = speedMultiplier;
                if (pc.IsGrounded) pc.CanJump = false;
                break;
            case TerrainEffectType.Ice:
                pc.SteeringControl = steeringControl;
                pc.LowGrip = true; // glide: no braking when idle, momentum carries
                break;
        }
    }
}

using UnityEngine;

// 2.5D force-based character controller. Moves on the XZ plane via acceleration
// toward a target velocity, so Unity physics drives interactions: PhysicMaterial
// friction (ice/mud), Rigidbody.drag (water), and AddForce zones (wind) all
// compose naturally instead of being overwritten. Small jump impulse, gravity
// handled by the Rigidbody.
[RequireComponent(typeof(Rigidbody))]
public class SolarpunkCharacterController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;        // target horizontal speed under input
    [SerializeField] private float acceleration = 40f;    // how hard we drive toward target
    [SerializeField] private float jumpForce = 6f;
    // Baseline drag is 0: accel-to-target already arrests horizontal motion when input is
    // released (target velocity 0 -> decel force), so we need no passive drag — and drag is
    // isotropic, which would damp jump/fall. Water zones raise this temporarily; ice keeps it low.
    [SerializeField] private float groundDrag = 0f;
    [SerializeField] private float groundCheckDistance = 0.12f;
    [SerializeField] private LayerMask groundLayers = ~0;
    // Ice low-grip is re-asserted by the zone every physics step. Latch it for a short grace
    // window so a single missed OnTriggerStay (e.g. player center crossing the trigger edge
    // while the capsule is still on the ice) doesn't snap the ground brake back on for a step
    // and bleed the slide. Grace ends well before the player is truly off the ice.
    [SerializeField] private float lowGripGrace = 0.2f;

    public Vector3 MoveInput => moveInput;
    public bool IsGrounded => isGrounded;
    /// <summary>Horizontal speed normalized 0-1 relative to moveSpeed.</summary>
    public float NormalizedSpeed => rb != null
        ? Mathf.Clamp01(new Vector2(rb.velocity.x, rb.velocity.z).magnitude / moveSpeed)
        : 0f;

    /// <summary>Multiplies steering force each physics step. Ice sets this low (slidey, weak
    /// steering, momentum dominates) — kept &gt;0 so the player can always escape ice. Auto-resets to 1.</summary>
    public float SteeringControl { get; set; } = 1f;

    /// <summary>Multiplies the target move speed each physics step. Water/Mud set this below 1 to
    /// slow the player noticeably (lowering the target, since drag/friction barely dents accel-to-target).
    /// Auto-resets to 1.</summary>
    public float SpeedMultiplier { get; set; } = 1f;

    /// <summary>Set false each physics step by a mud zone while grounded on it: blocks jumping
    /// ("mud stops vertical movement"). Auto-resets to true.</summary>
    public bool CanJump { get; set; } = true;

    /// <summary>Set true each physics step by an ice zone: the controller stops braking toward
    /// zero when there's no input, so momentum carries (glide). Steering still applies (scaled by
    /// SteeringControl) so the player can nudge off the ice. Auto-resets to false.</summary>
    public bool LowGrip { get; set; } = false;

    public Vector3 RbVelocityDirection { get; private set; }

    private Rigidbody rb;
    private Collider bodyCollider;
    private bool isGrounded;
    private Vector3 moveInput;
    private bool jumpQueued;
    private float lowGripTimer;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        bodyCollider = GetComponent<Collider>();
        rb.drag = groundDrag;
        rb.freezeRotation = true;
    }

    private void Update()
    {
        moveInput.x = Input.GetAxisRaw("Horizontal");
        moveInput.z = Input.GetAxisRaw("Vertical");
        RbVelocityDirection = rb.velocity.normalized;
        if (moveInput.sqrMagnitude > 1f) moveInput.Normalize();

        if (Input.GetButtonDown("Jump")) jumpQueued = true;
    }



    private void FixedUpdate()
    {
        UpdateGrounded();

        // Accelerate toward the input-driven target velocity (XZ only). External forces
        // (wind AddForce) and surface friction are left to the solver. SpeedMultiplier
        // lowers the target (water/mud slow); SteeringControl scales the force (ice = slidey,
        // weak steering so momentum carries, but never 0 so the player can't get stuck).
        Vector3 horizVel = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
        Vector3 inputDir = new Vector3(moveInput.x, 0f, moveInput.z);
        bool idle = inputDir.sqrMagnitude < 0.01f;
        // Latch low-grip: refresh the timer while the zone asserts it, otherwise decay it.
        // The brake stays off for the whole grace window, surviving single-step trigger gaps.
        if (LowGrip) lowGripTimer = lowGripGrace;
        else lowGripTimer -= Time.fixedDeltaTime;
        bool lowGrip = lowGripTimer > 0f;
        if (lowGrip)
        {
            // Ice: momentum carries, input only steers. With input, push in the input direction
            // WITHOUT the "- horizVel" brake term (that term is what kills the slide on normal
            // ground), so existing momentum is preserved and the velocity vector rotates toward
            // the input instead of being reset to it. Speed is capped to moveSpeed so the additive
            // force can't run away. Idle = no force, the frictionless surface keeps the glide.
            if (!idle)
            {
                rb.AddForce(inputDir * moveSpeed * acceleration * SteeringControl, ForceMode.Acceleration);
                Vector3 hv = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
                float maxSpeed = moveSpeed * SpeedMultiplier;
                if (hv.magnitude > maxSpeed)
                {
                    hv = hv.normalized * maxSpeed;
                    rb.velocity = new Vector3(hv.x, rb.velocity.y, hv.z);
                }
            }
        }
        else
        {
            // Normal ground: accelerate toward the input-driven target velocity (XZ only).
            // SpeedMultiplier lowers the target (water/mud slow); SteeringControl scales the
            // force (wind = weak self-correction so wind blows you).
            Vector3 targetVel = inputDir * moveSpeed * SpeedMultiplier;
            Vector3 dv = targetVel - horizVel;
            rb.AddForce(dv * acceleration * SteeringControl, ForceMode.Acceleration);
        }

        if (jumpQueued && isGrounded && CanJump)
        {
            Vector3 v = rb.velocity; v.y = 0f; rb.velocity = v;
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
            isGrounded = false;
        }
        jumpQueued = false;

        // Per-step terrain modifiers; zones re-assert them in OnTriggerStay (which fires
        // after FixedUpdate within the same physics step).
        SteeringControl = 1f;
        SpeedMultiplier = 1f;
        CanJump = true;
        LowGrip = false;
    }

    private void UpdateGrounded()
    {
        if (bodyCollider == null)
        {
            isGrounded = false;
            return;
        }

        Vector3 origin = bodyCollider.bounds.center;
        origin.y = bodyCollider.bounds.min.y + 0.02f;

        isGrounded = Physics.Raycast(
            origin,
            Vector3.down,
            groundCheckDistance,
            groundLayers,
            QueryTriggerInteraction.Ignore
        );
    }
}

using UnityEngine;

/// <summary>
/// Wrench rope/lasso (winch grapple). Hold Q to charge, release to fire. Grapples exactly
/// what the cursor is over (resolved by <see cref="PlayerMouseAimer"/>); the marker kind decides mode:
///  - a movable <see cref="RopePullable"/> → reel the object UP toward the player;
///  - a <see cref="RopeAnchor"/> → reel the PLAYER to the exact clicked surface point.
/// Winching is force-based (AddForce) so it composes with the rest of the physics. Blocked
/// while standing on mud (reuses the controller's CanJump signal). Wrench must be the active
/// item, like swing/throw. A LineRenderer draws the rope from the hand to the far end while reeling.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class RopeLassoController : MonoBehaviour
{
    [SerializeField] private RopeLassoConfig _config;
    [Tooltip("Rope visual. A child LineRenderer with 2 positions; enabled only while reeling.")]
    [SerializeField] private LineRenderer _ropeLine;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _controller;
    private Rigidbody _rb;

    private float _chargeTimer;
    private bool _charging;

    // Active winch state.
    private bool _pulling;
    private bool _selfPull;        // true: reel player to anchor; false: reel object to player.
    private Rigidbody _pullBody;   // the body receiving force.
    private Vector3 _anchorPoint;  // fixed far end for a self-pull.
    private float _pullElapsed;

    public bool IsCharging => _charging;
    public float ChargeNormalized => _config != null && _config.chargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.chargeTime)
        : 0f;
    public bool IsPulling => _pulling;

    /// <summary>Billboard visual centre, so the rope leaves from the sprite's hand, not the feet.</summary>
    public Vector3 HandPoint => _animDriver != null ? _animDriver.VisualCenter : transform.position;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _controller = GetComponent<SolarpunkCharacterController>();
        _rb         = GetComponent<Rigidbody>();
        if (_ropeLine != null)
        {
            _ropeLine.positionCount = 2;
            _ropeLine.enabled = false;
        }
    }

    private void Update()
    {
        // Mud blocks the lasso: the Mud TerrainEffectZone clears CanJump while grounded on it.
        bool onMud = _controller != null && !_controller.CanJump;
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !_pulling && !onMud;
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetKeyDown(KeyCode.Q))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetKey(KeyCode.Q))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetKeyUp(KeyCode.Q))
        {
            FireLasso();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void FireLasso()
    {
        if (_config == null) return;

        // Grapple exactly what the cursor is over (resolved by PlayerMouseAimer). The kind of
        // marker decides the mode: a RopePullable = reel it up to the player; a RopeAnchor =
        // reel the player to the exact clicked surface point. Range is gated here against that
        // precise hit point so min/maxRange are honoured regardless of object size.
        RopeAnchor anchor = _aimer.HoveredAnchor;
        RopePullable pullable = _aimer.HoveredPullable;
        if (anchor == null && pullable == null) return;     // nothing hovered → no grapple

        Vector3 grapplePoint = _aimer.HoveredGrapplePoint;
        float dist = Vector3.Distance(transform.position, grapplePoint);
        if (dist < _config.minRange || dist > _config.maxRange) return;

        if (pullable != null)
            BeginPull(selfPull: false, body: pullable.Body, anchorPoint: Vector3.zero);
        else
            BeginPull(selfPull: true, body: _rb, anchorPoint: grapplePoint);
    }

    private void BeginPull(bool selfPull, Rigidbody body, Vector3 anchorPoint)
    {
        if (body == null) return;
        _pulling = true;
        _selfPull = selfPull;
        _pullBody = body;
        _anchorPoint = anchorPoint;
        _pullElapsed = 0f;

        Vector3 far = selfPull ? anchorPoint : body.position;
        if (_animDriver != null) _animDriver.FaceWorldDirection(far - transform.position);
    }

    private void FixedUpdate()
    {
        if (!_pulling) return;
        if (_pullBody == null) { EndPull(); return; }

        _pullElapsed += Time.fixedDeltaTime;

        // Self-pull reels toward the fixed anchor; object-pull reels toward the (moving) player hand.
        Vector3 target = _selfPull ? _anchorPoint : HandPoint;
        Vector3 to = target - _pullBody.position;

        if (to.magnitude <= _config.stopRadius || _pullElapsed >= _config.pullTimeout)
        {
            EndPull();
            return;
        }

        _pullBody.AddForce(to.normalized * _config.pullForce, ForceMode.Acceleration);
        if (_pullBody.velocity.magnitude > _config.maxPullSpeed)
            _pullBody.velocity = _pullBody.velocity.normalized * _config.maxPullSpeed;

        // Suppress steering so movement input doesn't fight a self-reel (reasserted each step,
        // like a terrain zone; the controller auto-resets it).
        if (_selfPull && _controller != null)
            _controller.SteeringControl = _config.steeringDuringPull;
    }

    private void EndPull()
    {
        _pulling = false;
        _pullBody = null;
    }

    // Draw the rope from the hand to the far end while reeling.
    private void LateUpdate()
    {
        if (_ropeLine == null) return;
        if (_pulling && _pullBody != null)
        {
            _ropeLine.enabled = true;
            _ropeLine.SetPosition(0, HandPoint);
            _ropeLine.SetPosition(1, _selfPull ? _anchorPoint : _pullBody.position);
        }
        else
        {
            _ropeLine.enabled = false;
        }
    }
}

using UnityEngine;

public class Billboard : MonoBehaviour
{
    private Camera _mainCamera;

    private void Start()
    {
        _mainCamera = Camera.main;
    }

    private void LateUpdate()
    {
        if (_mainCamera == null) return;

        Vector3 directionToCamera = _mainCamera.transform.position - transform.position;

        float horizontalDist = new Vector2(directionToCamera.x, directionToCamera.z).magnitude;
        float pitchAngle = Mathf.Atan2(directionToCamera.y, horizontalDist) * Mathf.Rad2Deg;

        transform.rotation = Quaternion.Euler(pitchAngle, transform.eulerAngles.y, 0f);
    }
}

